// ── Class-based Singleton: lazy initialization ──────────────────
class DatabasePool {
  #connections = [];
  #maxSize;

  constructor(maxSize = 5) {
    if (DatabasePool._instance) {
      return DatabasePool._instance; // guard: return existing
    }
    this.#maxSize = maxSize;
    for (let i = 0; i < maxSize; i++) {
      this.#connections.push({ id: i, inUse: false });
    }
    DatabasePool._instance = this;
    console.log(`[DB Pool] Created with ${maxSize} connections`);
  }

  static getInstance(maxSize) {
    if (!DatabasePool._instance) {
      new DatabasePool(maxSize);
    }
    return DatabasePool._instance;
  }

  acquire() {
    const conn = this.#connections.find(c => !c.inUse);
    if (!conn) throw new Error('No free connections');
    conn.inUse = true;
    return conn;
  }

  release(conn) {
    conn.inUse = false;
  }

  get available() {
    return this.#connections.filter(c => !c.inUse).length;
  }
}

// First call creates the pool
const pool1 = DatabasePool.getInstance(3);
const pool2 = DatabasePool.getInstance();   // returns SAME instance

console.log(pool1 === pool2);               // true
console.log(pool1.available);               // 3

const conn = pool1.acquire();
console.log(pool2.available);               // 2  ← shared state!
pool1.release(conn);
console.log(pool2.available);               // 3

// ── Module singleton (idiomatic JS) ─────────────────────────────
// logger.js (imagine this in a separate file)
const _log = [];
const logger = {
  log(msg)  { _log.push({ ts: Date.now(), msg }); console.log('[LOG]', msg); },
  getLogs() { return [..._log]; },
};
// export default logger;  ← every importer gets the same object

// Simulated here:
const loggerA = logger; // 'imported' in module A
const loggerB = logger; // 'imported' in module B
loggerA.log('App started');
loggerB.log('User logged in');
console.log(loggerA.getLogs().length); // 2 — both logged to same store

// ── Singleton: structural skeleton ──────────────────────────────
class Singleton {
  static #instance = null;

  // Private constructor — prevent external `new`
  constructor() {
    if (Singleton.#instance) throw new Error('Use Singleton.getInstance()');
  }

  static getInstance() {
    if (!Singleton.#instance) {
      Singleton.#instance = new Singleton();
    }
    return Singleton.#instance;
  }

  // Shared behaviour / state
  doSomething() { return 'I am the one and only'; }
}

// ── Reset hook for tests (inject testability) ────────────────────
Singleton._resetForTest = () => { Singleton['#instance'] = null; };
// (True private fields can't be reset from outside — in tests
//  expose via a dedicated static method or use module mocking.)

const a = Singleton.getInstance();
const b = Singleton.getInstance();
console.log(a === b);          // true
console.log(a.doSomething()); // 'I am the one and only'

